<?php/* * 微信公众号服务 */namespace app\api\service\public;use app\api\service\CommService;use app\common\model\MallCustomer;use app\common\model\SystemWechatConfig;use EasyWeChat\Factory;use Exception;use support\exception\BusinessException;use support\Log;use think\facade\Db;class OfficialService extends CommService{    protected $app = [];    protected $app_id = '';    protected $wxlogin_redirect = '';    protected $category = 'official';    protected $is_debug = false;    public function __construct($param)    {        parent::_initialize($param);        $this->is_debug = $this->param['is_debug'] ?? false;        $where['group'] = 'official';        $where['appid'] = $this->param['app_id'];        $app_config = SystemWechatConfig::where($where)->field('appid,secret,redirect')->find();        if (empty($app_config)) {            return throwError('app_id错误');        }        if (empty($app_config['appid']) || empty($app_config['secret'])) {            return throwError('WeChat official account error');        }        $this->app_id = $app_config['appid'];        $this->wxlogin_redirect = $app_config['redirect'];        $config = [            'app_id' => $app_config['appid'],            'secret' => $app_config['secret'],            // 指定 API 调用返回结果的类型：array(default)/collection/object/raw/自定义类名            'response_type' => 'array',        ];        $this->app = Factory::officialAccount($config);    }    public function createQrCode($scene_value, $qr_type)    {        $this->data['qr_url'] = '';        switch ($qr_type) {            case 'temporary':                $qr_info = $this->app->qrcode->temporary($scene_value);                break;            case 'forever':                $qr_info = $this->app->qrcode->forever($scene_value);                break;        }        if (isset($qr_info['ticket'])) {            $this->data['qr_url'] = $this->app->qrcode->url($qr_info['ticket']);        }        return $this->data;    }    public function getWxAuthorizationUrl()    {        $this->data['url'] = $this->app->oauth->scopes(['snsapi_userinfo'])->redirect($this->wxlogin_redirect);        return $this->data;    }    public function doWxLogin($code)    {        $info = $this->getWxUserInfo($code);        $this->doLogin($info);        return $this->data;    }    public function getWxUserInfo($code)    {        $openid = '1234568790';        $nickname = 'yuepeng';        $avatar = 'http://www.baidu.com';        if (!$this->is_debug) {            $wechat_user_info = $this->app->oauth->userFromCode($code)->toArray();            if (isset($wechat_user_info['raw']['errcode'])) {                Log::channel('api')->info(json_encode($wechat_user_info));                throwError($wechat_user_info['raw']['errmsg'], $wechat_user_info['raw']['errcode']);            }            $openid = $wechat_user_info['id'];            $nickname = filter_emoji($wechat_user_info['nickname']);            $avatar = $wechat_user_info['avatar'];        }        $user['openid'] = $openid;        $user['nickname'] = $nickname;        $user['avatar'] = $avatar;        $user['app_id'] = $this->app_id;        $user['round_id'] = $this->round_info['round_id'];//        $user['channel'] = $this->param['channel'] ?? '';        $recommend_id = 0;//        if (!empty($this->param['sign_id'])) {//            $sign_info = $table->where('id', $this->param['sign_id'])->find();//            if ($sign_info) {//                $recommend_id = $sign_info['customer_id'];//            }//        }        $is_snapshotuser = $wechat_user_info['token_response']['is_snapshotuser'] ?? 0;        return ['user' => $user, 'recommend_id' => $recommend_id, 'is_snapshotuser' => $is_snapshotuser];    }    protected function doLogin($info)    {        Db::startTrans();        try {            if ($info['is_snapshotuser'] == 0) {                $MallCustomer = new MallCustomer();                $where['openid'] = $info['user']['openid'];                $data['user_info'] = $MallCustomer->doLogin($MallCustomer->findUser($where), $info['user'], true, $info['user']['app_id'], $info['recommend_id'], $this->category);                $data['round_info'] = $this->round_info;                $this->data = $data;            }            Db::commit();        } catch (Exception $e) {            Db::rollback();            throwError($e->getMessage());        }        return $this->data;    }    public function doSenselessLogin($code)    {        $info = $this->doSenselessUserInfo($code);        $this->doLogin($info);        return $this->data;    }    public function doSenselessUserInfo($code)    {        $openid = '1234568790';        if (!$this->is_debug) {            $wechat_user_info = $this->app->oauth->userSenselessFromCode($code)->toArray();            if (empty($wechat_user_info['id'])) {                throwError('微信登录失败');            }            $openid = $wechat_user_info['id'];        }        $user['openid'] = $openid;        $user['app_id'] = $this->app_id;        $user['round_id'] = $this->round_info['round_id'];        $recommend_id = 0;        $is_snapshotuser = $wechat_user_info['token_response']['is_snapshotuser'] ?? 0;        return ['user' => $user, 'recommend_id' => $recommend_id, 'is_snapshotuser' => $is_snapshotuser];    }    public function getJssdkConfigure()    {        if (!empty($this->param['url'])) {            $url = str_replace("amp;", "", $this->param['url']);            $this->app->jssdk->setUrl($url);        }        //JSAPI接口 文档：https://developers.weixin.qq.com/doc/offiaccount/OA_Web_Apps/JS-SDK.html#10        $APIs = array(            'updateAppMessageShareData',          //分享给朋友”及“分享到QQ            'updateTimelineShareData',            //分享到朋友圈”及“分享到 QQ 空间            //音频皆苦//            'startRecord',                      //开始录音//            'stopRecord',                       //停止录音//            'onVoiceRecordEnd',                 //监听录音自动停止接口//            'playVoice',                        //播放语音接口//            'pauseVoice',                       //暂停播放接口//            'stopVoice',                        //停止播放接口//            'onVoicePlayEnd',                   //监听语音播放完毕接口//            'uploadVoice',                      //上传语音接口//            'downloadVoice',                    //下载语音接口//            'translateVoice',                   //识别音频并返回识别结果接口            //图像接口//            'chooseImage',                      //拍照或从手机相册中选图接口//            'previewImage',                     //预览图片接口//            'uploadImage',                      //上传图片接口//            'downloadImage',                    //下载图片接口//            'getLocalImgData',                  //获取本地图片接口            //设备信息//            'getNetworkType',                   //获取网络状态接口//            'openAddress',                      //共享收货地址接口//            'openLocation',                     //*********使用微信内置地图查看位置接口******//            'getLocation',                      //*********获取地理位置接口****************//            'scanQRCode',                       //*********调起微信扫一扫接口**************//            'chooseWXPay',                      //*********发起一个微信支付请求************        );        $this->data['info'] = $this->app->jssdk->buildConfig($APIs, $debug = false, $beta = false, $json = false, $openTagList = []);        return $this->data;    }    public function sendMessage($touser, $template_id, $data, $url = '', $miniprogram = array())    {        $send_body = $this->getMessageTemplate($touser, $template_id, $data, $url, $miniprogram);        $send_res = $this->app->template_message->send($send_body);        if ($send_res['errcode'] != 200) {            throw new BusinessException($send_res['errmsg'], $send_res['errcode']);        }        return $this->data;    }    public function getMessageTemplate($touser, $template_id, $data, $url, $miniprogram)    {        $patterns = array(            '/{touser}/',            '/{url}/'        );        $replacements = array(            $touser,            $url        );        $template = config('official_template.' . $template_id);        //方法说明：preg_replace($pattern, $replacement, $subject, $limit, $count)  搜索subject中匹配pattern的部分， 以replacement进行替换。        $send_body = preg_replace($patterns, $replacements, $template);        $send_body = array_merge($send_body, ['data' => $data]);        if ($miniprogram) {            $send_body = array_merge($send_body, ['miniprogram' => $miniprogram]);        }        return $send_body;    }}